BEGIN;
CREATE TABLE IF NOT EXISTS platform_settings (setting_key TEXT PRIMARY KEY, setting_value JSONB NOT NULL DEFAULT '{}'::jsonb, updated_by UUID REFERENCES app_users(id) ON DELETE SET NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS notification_preferences (event_type TEXT PRIMARY KEY, telegram_enabled BOOLEAN NOT NULL DEFAULT FALSE, email_enabled BOOLEAN NOT NULL DEFAULT FALSE, updated_by UUID REFERENCES app_users(id) ON DELETE SET NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
INSERT INTO platform_settings(setting_key,setting_value) VALUES ('storefront', jsonb_build_object('heroTitle','Your entertainment. One simple subscription.','heroSubtitle','Stream movies and TV with simple plans, multiple concurrent streams and downloads on paid plans.','featureTitle','Everything you need to watch your way','supportEmail','','announcement','')), ('storefront_features', jsonb_build_array('Huge movie and TV library','Up to 3 concurrent streams on paid plans','Downloads included on paid plans','Watch on phones, TVs, tablets and browsers','Simple self-service account portal','24-hour trial available')) ON CONFLICT (setting_key) DO NOTHING;
INSERT INTO notification_preferences(event_type) VALUES ('customer.created'),('subscription.activated'),('subscription.expiring'),('payment.failed'),('server.offline'),('request.created') ON CONFLICT (event_type) DO NOTHING;
COMMIT;
